insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('virgin-islands-us-virgin-islands', '11C', 'Virgin Islands National Park', 'United States', 'Coral reefs, sugar ruins and Cinnamon Bay', 'future', 'verified', 'mountainValley', 'US Virgin Islands', '{"tropical","ocean","hiking","culture","family","parks"}', '{"tropical","serene","historic","coastal"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Trunk Bay Underwater Snorkel Trail","source":"https://www.nps.gov/viis/planyourvisit/snorkeling.htm","accessed":"2026-10-03","si":["tropical","ocean","family","senior"],"booking_route":"pay the Trunk Bay amenity fee on site; facilities open 8 a.m. to 4:00 p.m.","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":1,"blurb":"\"the Underwater Snorkel Trial, a great place for beginners and anyone who wants to learn about marine life\" - about 300 feet along the west side of Trunk Bay Cay with underwater plaques. Trunk Bay carries the park''s only expanded amenity fee: \"Individual Day Pass (16 years and older): $5.00\", \"Interagency Senior Pass: $2.50 for holder\". Beach wheelchairs and accessible paths to the water."},{"name":"Reef Bay Trail","source":"https://www.nps.gov/thingstodo/reef-bay-trail.htm","accessed":"2026-10-03","si":["hiking","culture","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"From the trailhead to the beach is about three miles one way\"; \"a steep strenuous hike\" with a 900-foot climb back, past \"ancient rock carvings left behind by the pre-Colombian Taino\", \"Danish sugar plantation ruins\" and \"stone walls from cattle grazing\"; \"During rainy season the waterfall can be spectacular.\""},{"name":"Annaberg Sugar Plantation","source":"https://www.nps.gov/thingstodo/annaberg-sugar-plantation.htm","accessed":"2026-10-03","si":["culture","senior","hiking"],"booking_route":"none needed - free historic site","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"On St. John''s north shore, remains of an 18th-19th century Danish colonial sugar plantation where over 600 enslaved Africans laboured; the NPS allows \"1-2 Hours\" and calls it \"the park''s most accessible historic plantation site.\" \"The trail from the parking lot to the historic district is fairly steep and rocky.\""},{"name":"Waterlemon Cay and Leinster Bay","source":"https://www.nps.gov/viis/planyourvisit/snorkeling.htm","accessed":"2026-10-03","si":["ocean","tropical","wildlife","hiking"],"booking_route":"none needed - free; reached on foot","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"Reached by the Leinster Bay Trail, about a 10-minute walk from the Annaberg parking lot: shallow coral heads on a sandy bottom plus deeper drop-offs with blue chromis and sea turtles. The NPS warns snorkellers off the cay''s north side for strong currents and to \"stand only in sand\"."},{"name":"Cinnamon Bay Nature Loop and Accessible Trail","source":"https://www.nps.gov/thingstodo/cinnamon-bay-nature-loop-and-accessible-trail.htm","accessed":"2026-10-03","si":["culture","senior","family","hiking"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"30-60 Minutes\": a self-guided walk through a historic sugar plantation site with signs on plantation-era life, bay rum and tyre palm trees; \"The first .09 miles of the Cinnamon Nature loop is accessible via the boardwalk... wheelchair and stroller friendly.\""},{"name":"Reef Bay Guided Hike","source":"https://www.nps.gov/viis/planyourvisit/rangerguidedtours.htm","accessed":"2026-10-03","si":["hiking","group","culture"],"booking_route":"FareHarbor link on the NPS ranger-programmes page","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":6,"blurb":"A ranger-led \"interpretive guided hike that will explore the history and culture of St. John\", \"just under 3 miles one way\", a \"STRENUOUS hike\" past the petroglyph site and sugar ruins, returning by a \"40-minute boat cruise\" to Cruz Bay; check-in 7:45 AM at the Visitor Center; bring sturdy shoes, 2-3 liters of water, lunch and sunscreen."},{"name":"Francis Bay Boardwalk and beach","source":"https://www.nps.gov/viis/planyourvisit/accessibility.htm","accessed":"2026-10-03","si":["wildlife","senior","tropical","family"],"booking_route":"none needed - free boardwalk and beach","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"a wheelchair accessible boardwalk to a beautiful salt pond, perfect for bird viewing\"; the NPS rates Francis Bay ideal for beginner snorkellers in calm water. Friends of Virgin Islands National Park leads a Francis Bay Bird Walk on Fridays at 7:30am from October 9, 2026 (friendsvinp.org)."},{"name":"Maho Bay sea turtles","source":"https://www.nps.gov/viis/planyourvisit/snorkeling.htm","accessed":"2026-10-03","si":["wildlife","ocean","family","tropical"],"booking_route":"none needed - free beach","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"Named by the NPS for sea turtle sightings in its seagrass beds; Salomon and Honeymoon bays, also on the NPS list, add white-sand beaches and fringing reefs."},{"name":"Ram Head Guided Hike","source":"https://www.nps.gov/viis/planyourvisit/rangerguidedtours.htm","accessed":"2026-10-03","si":["hiking","culture","group"],"booking_route":"seasonal dates on the park''s calendar of events; booking method not stated on the page read","commission_status":"unknown","commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":9,"blurb":"A ranger-led \"intermediate hike just under 2 and a half miles\" from the Salt Pond Bay parking lot, \"rocky and steep in some areas\", telling the story of the \"1733 African Revolution\"; run on \"seasonal dates on the calendar of events\". The NPS: \"In the early morning of November 23, 1733, a small group of enslaved people entered the Danish West India Company''s fort in Coral Bay\" (the-1733-akwamu-insurrection.htm)."},{"name":"Night Sky in the Park","source":"https://www.nps.gov/viis/planyourvisit/rangerguidedtours.htm","accessed":"2026-10-03","si":["family","senior","wildlife"],"booking_route":"none stated - meet at Cinnamon Bay on the published evenings","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"A ranger programme at Cinnamon Bay Beach and Campground \"every other Wednesday at 8:15pm, November through May\"; the NPS recommends a flashlight, long pants and insect repellent."},{"name":"Cruz Bay Visitor Center","source":"https://www.nps.gov/viis/planyourvisit/hours.htm","accessed":"2026-10-03","si":["family","senior","culture"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"1300 Cruz Bay Creek, St. John, VI 00830\", 340-776-6201; \"Monday-Thursday 8:15 a.m. to 4:00 p.m. Friday 8:15 a.m. to 1:30 p.m.\"; exhibits include coral displays and \"a raised-relief map of St. John\"; \"wheelchair-accessible entrance, parking, and restrooms\". The Friends of the park run the retail store here."},{"name":"Junior Ranger programme","source":"https://www.nps.gov/viis/learn/kidsyouth/index.htm","accessed":"2026-10-03","si":["family"],"booking_route":"none needed - free at the Visitor Center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"Ask a ranger at the Cruz Bay Visitor Center desk for the workbook: \"When you bring your Junior Ranger workbook back to the visitor center, you''ll get your Junior Ranger badge and be awarded the Junior Ranger program certificate.\" Fourth graders collect their Every Kid in a Park pass at the same desk."},{"name":"Hawksnest Beach","source":"https://www.nps.gov/viis/planyourvisit/accessibility.htm","accessed":"2026-10-03","si":["tropical","senior","family"],"booking_route":"none needed - free beach","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"\"wheelchair-accessible parking, restrooms, changing rooms, and accessible paths to water\"; the NPS advises \"It is not advisable to snorkel directly over the reef\" here - keep to the reef perimeters."},{"name":"Overnight moorings in the park","source":"https://www.nps.gov/viis/planyourvisit/fees.htm","accessed":"2026-10-03","si":["sailing","yacht","senior"],"booking_route":"Recreation.gov mobile app at park pay stations","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":14,"blurb":"\"Regular overnight fee: $26.00/night\"; \"Senior/Access Pass: $13.00/night\". The NPS: \"Visitors are encouraged to use the recreation.gov mobile app to pay overnight mooring fees\" by QR code at pay stations; boat exclusion areas are set in the Superintendent''s Compendium."},{"name":"Trunk Bay Cafe and Bar","source":"https://www.nps.gov/viis/planyourvisit/eatingsleeping.htm","accessed":"2026-10-03","si":["culinary","tropical","family"],"booking_route":"walk-up at Trunk Bay","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":15,"blurb":"One of the two cafes inside the park: \"Trunk Bay Café and Bar at Trunk Bay\". The Snack Shack and Bar operate \"10:00 a.m. to 4:00 p.m.\" (NPS hours page)."},{"name":"Reef-safe sunscreen for the reefs","source":"https://www.nps.gov/viis/planyourvisit/snorkeling.htm","accessed":"2026-10-03","si":["ocean","tropical","family"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":16,"blurb":"NPS: \"Please Use Reef Safe Sunscreen!\" The park tells snorkellers to check the ingredient list for chemicals such as oxybenzone and octocrylene that cause coral bleaching, because a \"reef safe\" label alone is no guarantee; the hiking page asks for reef-safe sunscreen too."},{"name":"Water for the trail - half a gallon per four hours","source":"https://www.nps.gov/viis/planyourvisit/hiking-in-viis.htm","accessed":"2026-10-03","si":["hiking","tropical"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":17,"blurb":"NPS: \"Bring plenty of water and snacks, ½ gal of water for each four hours of hiking is minimum recommendation.\" Wear \"cool, loose clothing and comfortable sturdy walking or hiking shoes\"; \"Many trails have limited (or no) cell phone access!\""},{"name":"Closed-toe shoes and repellent for Reef Bay","source":"https://www.nps.gov/thingstodo/reef-bay-trail.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral to rei.com (AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":18,"blurb":"NPS kit for the Reef Bay Trail: \"Sturdy, closed-toe shoes\", \"plenty of water, some snacks and a lunch, and a hat\", \"Mosquito repellent\" and \"a swimsuit if you''d like to take a dip\"; the surface \"can be slippery even when dry.\""},{"name":"Cinnamon Bay Beach & Campground - bare and group sites","source":"https://www.cinnamonbayvi.com/stay","accessed":"2026-10-03","si":["tropical","group","family","hiking"],"booking_route":"own website booking (bookings10.rmscloud.com) or 340-714-7144; groups by email","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"\"the only designated campground on St. John\" (USVI tourism board), inside the park on the North Shore. Bare sites \"Include a wood platform with rain cover, picnic table and charcoal grill\", \"2 adults and 2 kids max\"; bare sites with a 4-person tent and comfort kit; group tents where \"Each tent has two twin bunks and can sleep 4 people\", reserved through groups@cinnamonbayvi.com. Two-night minimum on pre-reserved stays; closed Sept. 1 - Oct. 31."},{"name":"Cinnamon Bay eco-tents and cottages","source":"https://www.cinnamonbayvi.com/stay","accessed":"2026-10-03","si":["glamping","family","tropical","romance"],"booking_route":"own website booking (bookings10.rmscloud.com) or 340-714-7144","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"Eco-tents: \"Each rental has a fan, light, electric outlet, queen size bed, linens, bath towels, cooking kit, picnic table, chairs on the porch and can comfortably sleep 2 people\"; family eco-tents add twin bunks and \"can sleep 4 people\". Concrete cottages for 4 with \"ceiling fans/lights, electric outlet, a queen bed, day bed/sofa (w/trundle)... mini fridge, grill\". Direct access to Cinnamon Bay Beach."},{"name":"Rain Tree Cafe and the Cinnamon Bay food truck","source":"https://www.cinnamonbayvi.com/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-up at Cinnamon Bay","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":21,"blurb":"At Cinnamon Bay Beach & Campground: the Rain Tree Cafe serves breakfast and dinner daily and a food truck serves lunch, drinks and ice cream. The NPS: \"meals are served in an open-air dining hall and grab and go food and beverage items are also available in the Cinnamon Bay food truck near the beach.\""},{"name":"Cinnamon Bay watersports rentals","source":"https://www.cinnamonbayvi.com/","accessed":"2026-10-03","si":["ocean","family","tropical"],"booking_route":"on site at Cinnamon Bay; info@cinnamonbayvi.com","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities"],"draw_rank":22,"blurb":"\"Cinnamon Bay Beach & Campground offers on-site kayak, paddleboard, snorkel gear and chair rentals\" (USVI tourism board); the campground''s own site lists kayaks, paddleboards, snorkel gear and beach chairs. Bare-site campers can reserve limited rental items in advance."},{"name":"Caribbean Dreams: Exploring the U.S. & British Virgin Islands in 10 Days","source":"https://www.tourradar.com/t/318735","accessed":"2026-10-03","si":["group","senior","family","tropical"],"booking_route":"TourRadar (tour 318735)","commission_status":"commissioned","commission":"operator","tier_absent_reason":"does-not-compete","commission_pct_low":7,"commission_pct_high":7,"commission_basis":"published","wells":["activities"],"draw_rank":23,"blurb":"A 10-day small-group tour by Across Caribbean Excursions sold on TourRadar, group size 2-8, \"All Ages Welcome\": it starts in Charlotte Amalie, ferries to St. John, and day 3 includes \"Hike Reef Bay Trail or explore sugar plantation ruins\" and \"Snorkeling at Trunk Bay and Cinnamon Bay\" in Virgin Islands National Park, then on by boat to Tortola. Accommodation, guide, select meals and transport included; flights and insurance not."},{"name":"Virgin Islands Ecotours","source":"https://www.viecotours.com/","accessed":"2026-10-03","si":["ocean","family","group","wildlife"],"booking_route":"FareHarbor (own website)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":24,"blurb":"Guided kayak, hike and snorkel trips on three islands, including \"Sea Turtle Kayak & Snorkel - North Shore St. John\" (3 hours, from $119), \"The Best of St. John: Kayak, Snorkel & Beach Picnic\" (5 hours, from $159) and \"Coral Bay Kayak, Turtles & Tacos\" (3 hours, from $89); kayak, SUP and snorkel-gear rentals. St. John base: 520 Mongoose Jct, Cruz Bay; (340) 779-2155."},{"name":"Cruz Bay Watersports","source":"https://www.cruzbaywatersports.com/","accessed":"2026-10-03","si":["sailing","ocean","family","group"],"booking_route":"FareHarbor (own website)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":25,"blurb":"\"Snorkel, Sail, Jet Ski and Day Trip to the British Virgin Islands from St. Thomas and St.\" John; departures from The Ritz-Carlton St. Thomas and Westin Frenchman''s Reef/St. John; private yacht and catamaran charters; over 30 years in the islands. (340) 244-1493. The USVI tourism board: its catamarans let you \"slip into the water at an unspoiled cay, diverse reef or off-the-beaten-path snorkeling spot\"."},{"name":"VI SNUBA Excursions","source":"https://www.visitusvi.com/experience/best-st-john-snorkeling-spots-tours/","accessed":"2026-10-03","si":["ocean","family","diveglobal"],"booking_route":"own website visnuba.com (not fetched)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":26,"blurb":"USVI tourism board: \"exciting tours that are a cross between snorkeling and scuba diving around the reefs of Trunk Bay\" (visnuba.com). Own page not fetched in this build."},{"name":"Ocean Surfari","source":"https://www.visitusvi.com/experience/best-st-john-snorkeling-spots-tours/","accessed":"2026-10-03","si":["ocean","sailing","group"],"booking_route":"own website (not fetched)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":27,"blurb":"USVI tourism board: \"Join an Ocean Surfari snorkeling excursion aboard the 47-foot Reef Surfari that takes guests for outings throughout Virgin Islands National Park\". Own page not fetched in this build."},{"name":"Red Hook - Cruz Bay passenger ferry","source":"https://www.viport.com/schedules-ferrycargoschedules","accessed":"2026-10-03","si":["tropical","family","senior"],"booking_route":"tickets at the ferry dock","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":28,"blurb":"Run by \"Transportation Services & Varlack Ventures\" ((340) 776-6282 and (340) 776-6412): \"Non-Resident One-way $8.15\", \"Child (2-11) One-way $1\"; weekday departures from Red Hook from 5:30 am to 11:30 pm. A Charlotte Amalie - Cruz Bay service leaves Charlotte Amalie at \"10:00 am, 3:00 pm, 5:30 pm\" (subject to seasonal change)."},{"name":"Red Hook - Cruz Bay car barges","source":"https://www.viport.com/schedules-ferrycargoschedules","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"operator online tickets or at the barge","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":29,"blurb":"Operators named by the Virgin Islands Port Authority: Big Red Barge, Global Marine LLC (Tug Life) and Love City Car Ferries; non-resident one-way \"$50\", round trip to \"$65\"; \"Purchasing your ticket online does not guarantee a spot on any barge at a specific time.\""},{"name":"Mongoose Junction, Cruz Bay","source":"https://www.visitusvi.com/st-john/an-outdoor-adventure-in-st-john/","accessed":"2026-10-03","si":["culture","senior","family"],"booking_route":"none needed - a shopping centre","commission_status":"none","tier_absent_reason":"not-sold","wells":["shop"],"draw_rank":30,"blurb":"USVI tourism board: a \"mosaic of stone walls and shaded courtyards\" in Cruz Bay, with Made in St. John (\"sells clothing designed and screen-printed on the island\") and the St. John Experience Gallery; Wharfside Village on the waterfront has shops \"specializing in handmade jewelry and gifts\"."},{"name":"St. John Brewers Tap Room","source":"https://www.stjohnbrewers.com/","accessed":"2026-10-03","si":["culinary","group"],"booking_route":"walk-in; online food ordering","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"\"Local craft beers, sodas and our Green Flash energy drink\" made on St. John; the Tap Room is on the \"2nd Floor Mongoose Junction, Cruz Bay\", \"Open Daily 12 PM TO 9 PM\", \"Serving Food 12 PM TO 8 PM\"; +1 340-715-7775."},{"name":"Lime Out","source":"https://www.limeoutvi.com/","accessed":"2026-10-03","si":["culinary","tropical","sailing"],"booking_route":"first-come for dining; shuttles booked through the own website","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"\"A floating taco and cocktail bar anchored in the bay\" in Coral Bay, boat access only, with floating lily pads and a swim-up bar; 10:30 AM to 4:30 PM, Sunday through Friday (closed Saturdays until mid-December). From St. John the Salt + Lime Express shuttle leaves Coral Bay''s dinghy dock ($30/person); from St. Thomas the Taco Taxi from Emerald Beach. No dining reservations. (340) 643-5333."},{"name":"The Lime Inn","source":"https://www.thelimeinn.com/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in (no reservation method on the page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"\"Tasty tacos & handcrafted tacos in the heart of Cruz Bay\" - the land-based sister of Lime Out; \"OPEN SUNDAY THRU FRIDAY / 3:00 PM - 9:00 PM [CLOSED SATURDAYS]\", happy hour 3:00-5:00 PM; info@limeinn.com."},{"name":"Ocean 362 at Gallows Point Resort","source":"https://www.gallowspointresort.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"through Gallows Point Resort (1-340-776-6434)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"\"modern Caribbean cuisine with fresh, local ingredients, complemented by stunning sunset views over the ocean\", on the Gallows Point peninsula in Cruz Bay; seasonal, with limited September availability. The USVI tourism board: \"an airy terrace just above Cruz Bay\"."},{"name":"Gallows Point Resort","source":"https://www.gallowspointresort.com/","accessed":"2026-10-03","si":["romance","tropical","senior"],"booking_route":"own website (gallowspoint.innfinity.com) or 1-800-323-7229","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":35,"blurb":"\"The only resort in Cruz Bay, St. John offering oceanfront accommodations\": 5 acres on a peninsula a 5-minute walk from town; one-bedroom suites facing Pillsbury Sound or Cruz Bay Harbor, each with king bed and full kitchen; complimentary ferry shuttle, 24/7 reception."},{"name":"The Westin St. John Resort Villas","source":"https://www.visitusvi.com/experience/top-10-usvi-resorts/","accessed":"2026-10-03","si":["family","tropical","group"],"booking_route":"Marriott Vacation Club / marriott.com (not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":36,"blurb":"USVI tourism board: \"Roomy villas and townhouses are perched up in the hills, but convenient shuttles make them easy to access\"; placed \"near Cruz Bay\" in the board''s St. John itinerary."},{"name":"Lovango Resort & Beach Club","source":"https://www.visitusvi.com/experience/top-10-usvi-resorts/","accessed":"2026-10-03","si":["romance","tropical"],"booking_route":"own website (not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":37,"blurb":"USVI tourism board: \"Book a villa, cottage or air-conditioned treehouse with spectacular views high above the island.\" Own page not fetched in this build."},{"name":"The Ritz-Carlton, St. Thomas","source":"https://www.visitusvi.com/experience/top-10-usvi-resorts/","accessed":"2026-10-03","si":["romance","senior","tropical","family"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":38,"blurb":"USVI tourism board: \"The ultimate luxury destination, with its immaculate beach, tropical landscaping and stunning views across Great Bay to St. John\"; a \"five-star hotel''s private white-sand beach along Great Bay\". Cruz Bay Watersports departs from the resort. Marriott''s own page was not fetched (brand pages refuse automated reads), so nothing else is stated."},{"name":"The Westin Beach Resort & Spa at Frenchman''s Reef","source":"https://www.visitusvi.com/experience/indulge-in-st-thomas-luxury-resorts/","accessed":"2026-10-03","si":["family","senior","tropical","wellness"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":39,"blurb":"USVI tourism board: \"A modern, airy take on classic island living\", with views of \"bright-blue Morningstar Bay\" on St. Thomas. Cruz Bay Watersports departs from Westin Frenchman''s Reef. Marriott''s own page was not fetched, so nothing else is stated."},{"name":"Morningstar Buoy Haus Beach Resort at Frenchman''s Reef, Autograph Collection","source":"https://www.visitusvi.com/experience/indulge-in-st-thomas-luxury-resorts/","accessed":"2026-10-03","si":["romance","senior","tropical"],"booking_route":"marriott.com (brand booking; not fetched)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":8,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":40,"blurb":"USVI tourism board: a \"private beach hugging the coastline of Morningstar Bay just steps from your villa-style guest room\" on St. Thomas. A Marriott Autograph Collection property by its own name; Marriott''s page was not fetched, so nothing else is stated."},{"name":"Marriott''s Frenchman''s Cove","source":"https://www.visitusvi.com/experience/top-10-usvi-resorts/","accessed":"2026-10-03","si":["family","group","tropical"],"booking_route":"Marriott Vacation Club / marriott.com (not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":41,"blurb":"USVI tourism board: \"Two- and three-bedroom villas are comfortable and family friendly, with kitchens and dining rooms\"; a \"multicolored, multistory\" resort that \"commands unmatched views of Pacquereau Bay from its hillside perch\" on St. Thomas."},{"name":"Bolongo Bay Beach Resort","source":"https://www.visitusvi.com/experience/top-10-usvi-resorts/","accessed":"2026-10-03","si":["family","tropical","romance"],"booking_route":"own website (not fetched)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":42,"blurb":"USVI tourism board: \"This all-inclusive boutique resort on the southern coast of St. Thomas offers comfortable rooms with either beach access or stunning views.\" Own page not fetched in this build."},{"name":"Friends of Virgin Islands National Park","source":"https://friendsvinp.org/","accessed":"2026-10-03","si":["culture","senior","group","family","wildlife"],"booking_route":"via friendsvinp.org (booking procedure not stated on the page read)","commission_status":"unknown","commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities","shop"],"draw_rank":43,"blurb":"A 501(c)(3) founded in 1988 that runs the Reef Bay hike, a Francis Bay Bird Walk (Fridays 7:30am from October 9, 2026), seminars, demonstrations and boat trips October-June, youth programmes (Learn to Swim, Learn to Fish, summer camps), a snorkelling app, and the retail store at the Visitor Center. (340) 779-4940."}],"faq":[{"q":"How do I get to Virgin Islands National Park?","a":"The NPS: \"You will need to fly to St. Thomas and take a ferry over. There is a ferry for pedestrians and a car barge as well.\"","source":"https://www.nps.gov/viis/planyourvisit/frequently-asked-questions.htm","accessed":"2026-10-03"},{"q":"Is there a ferry from St. Thomas to Virgin Islands National Park?","a":"Yes. The Virgin Islands Port Authority lists the Red Hook - Cruz Bay passenger ferry run by \"Transportation Services & Varlack Ventures\", \"Non-Resident One-way $8.15\", with weekday departures from Red Hook from 5:30 am to 11:30 pm, and a Charlotte Amalie - Cruz Bay service leaving Charlotte Amalie at \"10:00 am, 3:00 pm, 5:30 pm\" (subject to seasonal change). Car barges also run Red Hook - Cruz Bay.","source":"https://www.viport.com/schedules-ferrycargoschedules","accessed":"2026-10-03"},{"q":"Can you camp in Virgin Islands National Park?","a":"Yes, at Cinnamon Bay. The NPS: \"The campground is open seasonally. Make reservations by visiting Cinnamon Bay Resort & Campground''s official website.\" Its sites range from bare platforms to eco-tents and cottages.","source":"https://www.nps.gov/viis/planyourvisit/frequently-asked-questions.htm","accessed":"2026-10-03"},{"q":"When is the best time to visit Virgin Islands National Park?","a":"The NPS states: \"The park is busiest from November to April in a typical year.\" For the hurricane window, NOAA: \"The Atlantic hurricane season runs from June 1 to November 30\" (nhc.noaa.gov/climo).","source":"https://www.nps.gov/viis/planyourvisit/frequently-asked-questions.htm","accessed":"2026-10-03"},{"q":"How many acres is Virgin Islands National Park?","a":"\"Virgin Islands National Park is comprised of 7,259 acres of terrestrial habitat, which is about 60%, of the island''s land mass. The park also includes 5,650 acres of adjacent submerged lands.\"","source":"https://www.nps.gov/viis/planyourvisit/basicinfo.htm","accessed":"2026-10-03"},{"q":"Is Virgin Islands National Park open?","a":"The park is \"Open year-round 24 hours a day.\" The Visitor Center is open \"Monday-Thursday 8:15 a.m. to 4:00 p.m. Friday 8:15 a.m. to 1:30 p.m.\" and closed Thanksgiving Day, December 25 and July 4; Trunk Bay facilities open \"8 a.m. to 4:00 p.m.\"","source":"https://www.nps.gov/viis/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"Where is the Virgin Islands National Park visitor center?","a":"At \"1300 Cruz Bay Creek, St. John, VI 00830\", phone 340-776-6201.","source":"https://www.nps.gov/viis/planyourvisit/index.htm","accessed":"2026-10-03"},{"q":"What is there for kids in Virgin Islands National Park?","a":"The Junior Ranger programme: ask a ranger at the Cruz Bay Visitor Center for the workbook, and \"When you bring your Junior Ranger workbook back to the visitor center, you''ll get your Junior Ranger badge and be awarded the Junior Ranger program certificate.\" Fourth graders collect their Every Kid in a Park pass at the same desk.","source":"https://www.nps.gov/viis/learn/kidsyouth/index.htm","accessed":"2026-10-03"},{"q":"Does the Virgin Islands have all-inclusive resorts?","a":"The USVI tourism board lists Bolongo Bay Beach Resort: \"This all-inclusive boutique resort on the southern coast of St. Thomas offers comfortable rooms with either beach access or stunning views.\"","source":"https://www.visitusvi.com/experience/top-10-usvi-resorts/","accessed":"2026-10-03"}],"seo":{"meta_title":"Virgin Islands National Park: Trunk Bay, Reef Bay & Cinnamon Bay | TravelWell","meta_description":"No entrance fee, Trunk Bay''s underwater snorkel trail, the Reef Bay petroglyph hike, Cinnamon Bay camping, and the ferry from St. Thomas to St. John.","slug":"virgin-islands-national-park-us-virgin-islands","primary_keyword":"Virgin Islands National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Trunk Bay St. John Virgin Islands National Park"}}'::jsonb, 94),
  ('banff-canada', '13A', 'Banff', 'Canada', 'The Rockies with a railway town at their feet', 'live', 'verified', 'mountainValley', 'The Rockies', '{"culture","family","hiking","ski","wellness"}', '{}', '{"essential","comfort"}', null, 'anchor', '{"key_facts":["The FCDO names no advisory against travel anywhere in Canada; its alert_status field is empty. Source: gov.uk/foreign-travel-advice/canada, reviewed 2026-06-02, read 2026-08-20.","4,515,000 visitors in 2025 — the highest to date, 7.14% above 2024; peak-summer visitation up 9%. Source: Parks Canada, Banff National Park Annual Report 2025.","Moraine Lake Road is closed to personal vehicles year-round. Source: parks.canada.ca Banff bulletin, read 2026-08-20.","Shuttle reservations opened 15 April 2026 at 8am MDT; 40% of seats released that day, 60% at 8am MDT two days before departure. Source: parks.canada.ca, read 2026-08-20.","The Canada Strong Pass with Parks Canada ends 7 September 2026; a valid pass is required from 8 September. Source: parks.canada.ca Banff fees, modified 2026-02-12.","Roam Public Transit carried 2,294,048 passengers in the park in 2025, up 12% on 2024. Source: Parks Canada Banff Annual Report 2025.","SkiBig3 spans 7,948 acres across Banff Sunshine Village, Lake Louise Ski Resort and Mt Norquay, with 2 gondolas and 32 chairlifts; Lake Louise alone is 4,200 acres. Source: skibig3.com, read 2026-08-20."],"safety":{"emergency":"911 — FCDO, Canada travel advice, Health: \"Dial 911 and ask for an ambulance.\" Read 2026-08-20.","hospital":"Banff Mineral Springs Hospital (Banff townsite) — operational fact, source pin outstanding","activity_note":"ALTITUDE — and the FCDO names this destination by name. Source: https://www.gov.uk/foreign-travel-advice/canada , Health, verbatim: \"Altitude sickness is a risk in parts of Canada, including skiing and hiking destinations in the Canadian Rockies such as Banff and Lake Louise.\" It also names biting insects and ticks, and mpox, as health risks in Canada. Read 2026-08-20.","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/canada","read":"2026-09-01T16:20:12Z","page_updated":"2026-06-02T17:02:41+01:00","source_country":"canada","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"content_ready_by":"2026-03-25","fire_date":"2026-04-01","booking_window_opens":"2026-04-15","event":"2026-06-01","inflection":"Parks Canada shuttle reservation launch, 15 April 2026 08:00 MDT — the moment a Banff summer becomes bookable or does not","peak":"July–August; 2025 peak-summer visitation up 9% and frontcountry campgrounds sold out","note":"Second, softer inflection: 60% of shuttle seats release at 08:00 MDT two days before departure. Source: parks.canada.ca, read 2026-08-20."},"jewels":[{"name":"Moraine Lake at first light","blurb":"Shuttle-only access with 4am and 5am departures; the road is closed to cars all year.","si":"hiking","tier_absent_reason":"not-sold","when":"1 June – 12 October","commission":"none held — Parks Canada is a government agency","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["hiking"],"shelf_fit":{"culture":"destination","family":"destination","hiking":"primary","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Lake Louise Lakeshore","blurb":"On Parks Canada''s own top ten; reached by the Lakeshore shuttle from 15 May.","si":"hiking","tier_absent_reason":"not-sold","when":"15 May – 12 October","commission":"none held — Parks Canada is a government agency","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["hiking"],"shelf_fit":{"culture":"destination","family":"destination","hiking":"primary","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Banff Upper Hot Springs","blurb":"A public thermal pool run by Parks Canada; $19.75 adult, $64.25 family, locker token included.","si":"wellness","when":"year-round","tier":"essential","commission":"none held — Parks Canada is a government agency","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["family","wellness"],"shelf_fit":{"culture":"destination","family":"evidenced","hiking":"destination","ski":"destination","wellness":"primary"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The Icefields Parkway","blurb":"Parks Canada: \"this 230 km drive winds through glaciers, emerald lakes, and broad sweeping valleys\". A full day out and back.","si":"family","tier_absent_reason":"not-sold","when":"May – October","commission":"none held","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["family"],"shelf_fit":{"culture":"destination","family":"primary","hiking":"destination","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Banff Gondola to the Sulphur Mountain summit","blurb":"An eight-minute ride; a one-way descent is half the price of admission and under-5s are free.","si":"family","when":"year-round","tier":"comfort","commission":"not contracted — Pursuit / Banff Jasper Collection","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["family","hiking"],"shelf_fit":{"culture":"destination","family":"primary","hiking":"evidenced","ski":"destination","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Johnston Canyon","blurb":"On Parks Canada''s top ten and connected by Roam Public Transit.","si":"hiking","tier_absent_reason":"not-sold","when":"year-round","commission":"none held","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["hiking"],"shelf_fit":{"culture":"destination","family":"destination","hiking":"primary","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Tunnel Mountain summit","blurb":"Parks Canada: \"the 2.4 km trail to this summit provides views across the town and Bow Valley\".","si":"hiking","tier_absent_reason":"not-sold","when":"May – October","commission":"none held","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["hiking"],"shelf_fit":{"culture":"destination","family":"destination","hiking":"primary","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Lake Minnewanka Loop","blurb":"On Parks Canada''s top ten and connected by Roam Public Transit.","si":"family","tier_absent_reason":"not-sold","when":"May – October","commission":"none held","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["family"],"shelf_fit":{"culture":"destination","family":"primary","hiking":"destination","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The Banff Legacy Trail","blurb":"Parks Canada: \"29 km of paved paths and roadways from Canmore to the Bow valley Parkway\".","si":"family","tier_absent_reason":"not-sold","when":"May – October","commission":"none held","wells":["activities"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["family","hiking"],"shelf_fit":{"culture":"destination","family":"primary","hiking":"evidenced","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Cave and Basin National Historic Site","blurb":"Where the national park began; first on Parks Canada''s top ten.","si":"culture","tier_absent_reason":"not-sold","when":"year-round","commission":"none held — Parks Canada is a government agency","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","family":"destination","hiking":"destination","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Banff Park Museum National Historic Site","blurb":"$5.00 adult, $4.50 senior, youth free.","si":"culture","when":"year-round","tier":"essential","commission":"none held — Parks Canada is a government agency","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["culture"],"shelf_fit":{"culture":"primary","family":"destination","hiking":"destination","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Vermilion Lakes Drive","blurb":"On Parks Canada''s top ten; a short drive from the townsite.","si":"family","tier_absent_reason":"not-sold","when":"year-round","commission":"none held","wells":["move"],"wells_basis":"derived from name/blurb/hook","si_all":["family"],"shelf_fit":{"culture":"destination","family":"primary","hiking":"destination","ski":"destination","wellness":"destination"},"commission_lane":["none"],"commission_embedded":false,"commission_basis":"lane"},{"name":"SkiBig3 — Sunshine, Lake Louise and Norquay","blurb":"7,948 acres across three areas, 2 gondolas and 32 chairlifts; Sunshine holds the longest non-glacial season in Canada.","si":"ski","when":"early November – late May","tier":"comfort","commission":"not contracted — SkiBig3","wells":["activities","move"],"wells_basis":"full pass 2026-10-05, additive — text","si_all":["ski"],"shelf_fit":{"culture":"destination","family":"destination","hiking":"destination","ski":"primary","wellness":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"}],"faq":[{"q":"What is the current advisory for Canada, and can I book it?","a":"The UK Foreign, Commonwealth & Development Office publishes travel advice for Canada and names no advisory against travel to any part of the country — its machine-readable alert field is empty — so there is no restriction standing between you and a booking. Its own words on the same page are \"No travel can be guaranteed safe. Read all the advice in this guide.\" We link the advice and we do not summarise it.","source":"https://www.gov.uk/foreign-travel-advice/canada, reviewed 2026-06-02, read 2026-08-20","si_tag":"safety","accessed":"2026-08-20"},{"q":"Can I just drive to Moraine Lake?","a":"No. Moraine Lake Road is closed to personal vehicles year-round. Access is the Parks Canada shuttle, a licensed commercial operator, a valid government-issued accessible parking placard, or being a registered guest of Moraine Lake Lodge. Free parking is at the Lake Louise Park and Ride, 1 Whitehorn Road.","source":"parks.canada.ca Banff bulletin and shuttle pages, accessed 2026-08-20","si_tag":"planning","accessed":"2026-08-20"},{"q":"When do the shuttle seats go on sale, and how do I actually get one?","a":"Reservations for 2026 opened 15 April at 8am MDT and only 40% of seats went that day. The other 60% are released at 8am MDT two days before departure, so a missed launch is not a lost trip. Book through the Parks Canada Reservation Service or 1-877-737-3783. The earliest Moraine Lake departures are 4am and 5am.","source":"parks.canada.ca, Visiting Lake Louise and Moraine Lake, accessed 2026-08-20","si_tag":"planning","accessed":"2026-08-20"},{"q":"Does my park pass cover the hot springs, the museum and the shuttle?","a":"No — each is charged separately. Banff Upper Hot Springs is $19.75 adult, $17.25 senior, $17.25 youth 3-17, free under 3 and $64.25 family, with a locker token included; swimsuit rental $5.00 and towel $3.00. The Banff Park Museum National Historic Site is $5.00 adult, $4.50 senior and free for youth. The shuttle is $12.75 adult on top of the reservation fee. All CAD.","source":"parks.canada.ca fee pages for Banff Upper Hot Springs, Banff Park Museum NHS and Banff National Park, accessed 2026-08-20","si_tag":"value","accessed":"2026-08-20"},{"q":"Is it worth coming outside July and August?","a":"Peak-summer visitation rose 9% in 2025 and the frontcountry campgrounds sold out, totalling 292,033 site nights across the year. The shuttle season runs to 12 October and the ski season runs to mid-May at Sunshine, and between those two the park is materially quieter.","source":"Parks Canada, Banff National Park Annual Report 2025, accessed 2026-08-20","si_tag":"planning","accessed":"2026-08-20"},{"q":"How long is the drive up the Icefields Parkway?","a":"Parks Canada describes it as \"this 230 km drive winds through glaciers, emerald lakes, and broad sweeping valleys\". It is a full day out and back, not an afternoon.","source":"parks.canada.ca, Banff top ten, accessed 2026-08-20","si_tag":"planning","accessed":"2026-08-20"}],"seo":{"slug":"banff-canada","canonical":"/destination/banff-canada","primary_keyword":"Banff National Park","keywords":["Banff National Park","Moraine Lake shuttle","Lake Louise","Banff park pass","Banff Upper Hot Springs","Icefields Parkway","SkiBig3"],"schema":["Article","FAQPage"],"content_freshness":"2026-08-20","languages":["en","fr"],"language_note":"Every Parks Canada page cited here is published in French by the same authority, so a French edition has a first-party source already.","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-08-20","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/canada","read":"2026-08-20T14:54:02Z","source_updated":"2026-06-02T17:02:41+01:00"}]},"meta_title":"Banff, Canada — the Rockies with a railway town at their feet","meta_description":"What a Banff trip actually requires: Moraine Lake Road is closed to cars year-round, the shuttle is reservation-gated from 15 April, and the park pass does not cover the hot springs. Government prices, sourced and dated."},"booking":{"book_suppressed":false,"authority":"UK FCDO","url":"https://www.gov.uk/foreign-travel-advice/canada","read":"2026-08-20","note":"The FCDO names no advisory against travel anywhere in Canada. That is an absence of restriction and never a green badge. No numeric level is assigned on this row.","fcdo":{"posture":"1","_posture_is_ours":"OUR classification of the FCDO''s page, never her booking posture. The FCDO publishes no level and we assign none."},"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["ski","hiking","wellness","family"],"ultra":null,"source_verified":"2026-08-20","hero":{"query":"Banff, Canada"},"orbit":[],"orbit_country":[]}'::jsonb, 0),
  ('vancouver-canada', '13A', 'Vancouver', 'Canada', 'Sea, city and mountains at once', 'live', 'stub', 'oceanAerial', null, '{}', '{}', '{}', null, null, null, 1),
  ('alta-utah', '12A', 'Alta', 'United States', 'America''s purist powder', 'live', 'verified', 'northernLights', 'Utah Canyon Country', '{"adventure","culinary","entertainment","expedition","family","romance","ski","wellness"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Alta = head of Little Cottonwood Canyon, INDEPENDENT (Ikon Pass PARTNER + Mountain Collective member; Ikon add-on $859 / Ikon Base $359); SKI-ONLY (no snowboarding - one of just three US resorts, with Deer Valley + Mad River Glen)","Both a ski area AND a real incorporated TOWN (~8,560 ft, ~228 residents, founded 1865 silver camp) - one of the highest towns in the US; genuinely high base 8,530 ft / summit 11,068 ft","ONE OF AMERICA''S OLDEST SKI AREAS: Collins chairlift opened Jan 1939 (2nd chairlift in the US after Sun Valley); Alf Engen hired 1935; Sunnyside six-pack (2022) modernization","~2,614 acres, 2,538 ft lift-served vertical, 116+ runs, ~55% advanced-expert; ~500-547 in snow (''Greatest Snow on Earth'', record ~900 in 1982-83); no night skiing","Joint Alta-Snowbird (''Alta-Bird'') ticket since 2002 + Mineral Basin interconnect; classic European-style ski LODGES (Alta Lodge 1940, Rustler 1947 half-board, Snowpine luxe ~2019, Alta Peruvian, Goldminer''s Daughter) - purist lodge culture, NOT a luxury village","US-TRAFFIC CANDOR: town-cited ~500k visitors/yr is a CONSENSUS ESTIMATE, not an audited count; heavy SL-valley powder-day day-trips","NO on-site cat/heli - Wasatch Powderbird is a SEPARATE operation (Snowbird/POWDR family), not an Alta product; NO natural hot springs (protected drinking-water watershed - dogs banned; lodge hot tubs man-made); prices dynamic","SLC ~29-32 mi / ~45 min-1 hr via SR-210 (canyon permitting); CANYON SAFETY SPINE: SR-210 winter dead-end + traction law, UDOT avalanche closures, INTERLODGE (official legal indoor confinement via Alta Central - among the most avalanche-managed inhabited places in NA)"],"safety":{"emergency":"911 (medical/fire/rescue); Town of Alta Marshal''s Office (801) 742-3522 for local law enforcement; alert ski patrol on-mountain","hospital":"No in-canyon hospital - full-service ERs down-canyon in Salt Lake valley (~45 min-1 hr via SR-210, canyon-access permitting); verify nearest facility","malaria":"none","yellow_fever":"not required","activity_note":"ALTITUDE (base ~8,530 ft GENUINELY HIGH - higher than many resorts'' summits; summit ~11,068 ft; real AMS risk for sea-level arrivals - hydrate, ease alcohol, consider a valley night to acclimatise, descend if worsening); AVALANCHE life-safety spine (in-bounds patrolled/controlled; hike-to + backcountry severe) - Utah Avalanche Center (UAC) ''Salt Lake'' region - VERIFY exact zone (UAC page 403); beacon/probe/shovel + guide, never duck ropes; NO on-site cat/heli (Powderbird separate); SR-210 winter DEAD-END + traction law + UDOT avalanche closures + INTERLODGE (legal indoor confinement via Alta Central - follow Town/lodge instructions; exact ordinance verify); tree-wells; cold + intense high-elevation UV","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/usa","read":"2026-09-01T16:18:24Z","page_updated":"2026-08-18T10:29:04+01:00","source_country":"usa","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"Deep winter + storm/powder days (Christmas/NY, Presidents'' Week, any big storm cycle); heavy SL-valley day-trip traffic on powder mornings","shoulder":"early season (Dec), Jan midweek, long high-altitude spring (Apr)","green":"summer + fall (canyon quiets, no lift-served skiing) + Oct-Nov lull","booking_lead":"Christmas/NY + Presidents'' + the lodges (half-board, limited beds) 3-6 mo; storm-chasing powder trips opportunistic; Alta/Ikon passes by early summer (best-price deadline)","off_season_specials":"long spring skiing; midweek value; lodge half-board packages","event_peaks":"Christmas/NY, MLK + Presidents'', spring-skiing events (2026-27 calendar unverified)","fire_date":"FIRE spring early-bird (Apr-Jun) Alta/Ikon renewals (best-price deadline) + long-spring push; fire again Sep-Nov + storm-triggered powder alerts"},"jewels":[{"name":"Ski America''s purist powder mountain","status":"live","tier":"comfort","price_band":"window dynamic; package best value","timing":"ski Dec-Apr","draw_rank":1,"hook":"ski-only, no snowboards, no built village — just ~500 inches of dry Wasatch powder over legendary steep terrain","si":"ski","blurb":"ski-only, no snowboards, no built village — just ~500 inches of dry Wasatch powder over legendary steep terrain","when":"ski Dec-Apr","commission":"DMC/ski-op 10-15% (embedded-capable)","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ski"],"shelf_fit":{"adventure":"destination","culinary":"destination","entertainment":"destination","expedition":"destination","family":"destination","romance":"destination","ski":"primary","wellness":"destination"},"commission_pct_low":10,"commission_pct_high":15,"commission_lane":["operator","DMC"],"commission_embedded":true,"commission_basis":"band+lane"},{"name":"Chase deep-powder days on Baldy + Devil''s Castle","status":"live","tier":"premier","price_band":"within package","timing":"powder heart Dec-Mar","draw_rank":2,"hook":"Alta''s legendary steep, hike-to terrain holds some of the best lift-accessed powder skiing in the world","si":"ski","blurb":"Alta''s legendary steep, hike-to terrain holds some of the best lift-accessed powder skiing in the world","when":"powder heart Dec-Mar","commission":"within package","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["ski"],"shelf_fit":{"adventure":"destination","culinary":"destination","entertainment":"destination","expedition":"destination","family":"destination","romance":"destination","ski":"primary","wellness":"destination"},"commission_lane":["package"],"comm