  ('beaver-creek-colorado', '12A', 'Beaver Creek', 'United States', 'Heated escalators, 3 p', 'live', 'verified', 'northernLights', 'The Colorado Rockies', '{"adventure","culinary","entertainment","expedition","family","romance","ski","wellness"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'emerging', '{"key_facts":["Beaver Creek = Vail Resorts / Epic; a PURPOSE-BUILT 1980 luxury resort village (Beaver Creek Village + Bachelor Gulch + Arrowhead) - NOT a historic town; ~10 mi west of Vail","~2,082 acres, ~150 trails, vertical 3,340 ft (base 8,100 / summit 11,440), ~25 lifts; terrain ~19 beg/43 int/38 adv; ~310 in snow + ~605 ac snowmaking; beginner-friendly up top","Signature touches: heated village escalators + free 3 p.m. chocolate-chip cookies daily","Genuine ULTRA bed base: Ritz-Carlton Bachelor Gulch (21,000 sq-ft spa), Park Hyatt Beaver Creek, The Osprey (RockResort, ~26 ft to a chairlift - closest in NA), The Pines Lodge, Beaver Creek Lodge","Dining: Splendido at the Chateau (Michelin-listed) + Beano''s Cabin (snowcat-sleigh dinner)","MARQUEE: Stifel Birds of Prey FIS Alpine World Cup (Birds of Prey course) - largest edition yet 3-13 Dec 2026 (men''s + women''s, 7 races/2 weekends)","NO in-bounds cat- or heli-skiing (guided BC + scenic snowcat/snow-coach to Camp Hale + McCoy Park snowshoe only; CO heli = Telluride/Silverton); NO natural hot springs on-site (Glenwood ~51-60 mi)","EGE ~17 mi (very close); DEN ~130 mi; Vail Health Hospital (Level III trauma, ~20 min) + slopeside Beaver Creek Medical Center; US-TRAFFIC CANDOR ~#11 consensus, not published"],"safety":{"emergency":"911 (police/fire/medical/rescue dispatch); alert ski patrol on-mountain","hospital":"Vail Health Hospital (Vail, ~20 min) - Level III Trauma Center + helipad; slopeside Beaver Creek Medical Center (outpatient ED of Vail Health)","malaria":"none","yellow_fever":"not required","activity_note":"ALTITUDE (base ~8,100 ft, summit ~11,440 ft - AMS real; acclimatize, hydrate, ease alcohol, descend if worsening); AVALANCHE backcountry - CAIC ''Vail & Summit County'' zone daily bulletin (by ~4:30 PM), beacon/probe/shovel + guide, never duck ropes; tree-wells; cold + intense UV; I-70 Traction Law (Sept 1-May 31, Dotsero-Morrison) escalates to Chain Law - check CDOT cotrip.org","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/usa","read":"2026-09-01T16:18:24Z","page_updated":"2026-08-18T10:29:04+01:00","source_country":"usa","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter (Christmas/NY, MLK, Presidents'', Feb-Mar) + Birds of Prey World Cup (early Dec); powder heart Jan-Mar","shoulder":"early season (late Nov-mid Dec outside Birds of Prey), Jan midweek, late-Mar spring (2025-26 closed early 29 Mar)","green":"May-Jun + Oct-Nov lull","booking_lead":"Christmas/NY + Presidents'' + Ritz/Park Hyatt + Birds of Prey week 4-8 mo; regular winter 3-6 mo; spring 1-3 mo","off_season_specials":"late-March value; summer hiking/golf (Bachelor Gulch); Birds-of-Prey-week luxury packages","event_peaks":"Christmas/NY, MLK + Presidents'', spring break, Birds of Prey World Cup (3-13 Dec 2026 - verify)","fire_date":"FIRE spring early-bird (Apr-Jun) Epic renewals + luxury pre-book; fire again Sep-Nov with a Birds-of-Prey luxury-package push"},"jewels":[{"name":"Ski the beginner-friendly high country","status":"live","tier":"comfort","price_band":"window dynamic; package far better value","timing":"ski Nov-Apr","draw_rank":1,"hook":"rare top-of-mountain green terrain and a smooth, uncrowded luxury mountain make Beaver Creek unusually welcoming — the polished all-ability week","si":"ski","blurb":"rare top-of-mountain green terrain and a smooth, uncrowded luxury mountain make Beaver Creek unusually welcoming — the polished all-ability week","when":"ski Nov-Apr","commission":"DMC/ski-op 10-15% (embedded-capable)","wells":